arguments.prompt:
You are implementing a logistics shipment tracking Blazor Web App. The project is already scaffolded at `/tmp/sv-59ddc6c217774c5aac0c6dd37751acac/ShipmentTracker/` with Interactive Auto Global mode and Individual authentication.

**Project structure:**
- Server project: `ShipmentTracker/ShipmentTracker/`
- Client project: `ShipmentTracker/ShipmentTracker.Client/`
- Solution file: `ShipmentTracker/ShipmentTracker.sln`

**Key architectural rule for Auto mode:** Interactive components must live in `.Client` project. They CANNOT access DbContext directly. Data access must go through HTTP APIs (Minimal API endpoints on server, HttpClient calls from client). Both Program.cs files must register matching service interfaces.

## Tasks to complete:

### 1. Create shared models in `.Client` project

Create `ShipmentTracker.Client/Models/ShipmentStatus.cs`:
```csharp
namespace ShipmentTracker.Client.Models;

public enum ShipmentStatus
{
    Pending,
    PickedUp,
    InTransit,
    OutForDelivery,
    Delivered,
    Cancelled
}
```

Create `ShipmentTracker.Client/Models/ShipmentDto.cs`:
```csharp
namespace ShipmentTracker.Client.Models;

public class ShipmentDto
{
    public int Id { get; set; }
    public string TrackingNumber { get; set; } = string.Empty;
    public string Origin { get; set; } = string.Empty;
    public string Destination { get; set; } = string.Empty;
    public ShipmentStatus Status { get; set; }
    public DateTime ShippedDate { get; set; }
    public DateTime? EstimatedDelivery { get; set; }
    public DateTime? ActualDelivery { get; set; }
    public string RecipientName { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
}
```

### 2. Create service interface in `.Client` project

Create `ShipmentTracker.Client/Services/IShipmentService.cs`:
```csharp
namespace ShipmentTracker.Client.Services;

using ShipmentTracker.Client.Models;

public interface IShipmentService
{
    Task<List<ShipmentDto>> GetAllShipmentsAsync();
    Task<ShipmentDto?> GetShipmentByTrackingNumberAsync(string trackingNumber);
    Task<ShipmentDto> CreateShipmentAsync(ShipmentDto shipment);
    Task<ShipmentDto> UpdateShipmentStatusAsync(int id, ShipmentStatus status);
}
```

### 3. Create HttpClient-based implementation in `.Client` project

Create `ShipmentTracker.Client/Services/ShipmentHttpService.cs`:
```csharp
using System.Net.Http.Json;
using ShipmentTracker.Client.Models;

namespace ShipmentTracker.Client.Services;

public class ShipmentHttpService(HttpClient httpClient) : IShipmentService
{
    public async Task<List<ShipmentDto>> GetAllShipmentsAsync()
    {
        return await httpClient.GetFromJsonAsync<List<ShipmentDto>>("api/shipments") ?? [];
    }

    public async Task<ShipmentDto?> GetShipmentByTrackingNumberAsync(string trackingNumber)
    {
        var response = await httpClient.GetAsync($"api/shipments/track/{trackingNumber}");
        if (response.StatusCode == System.Net.HttpStatusCode.NotFound)
            return null;
        response.EnsureSuccessStatusCode();
        return await response.Content.ReadFromJsonAsync<ShipmentDto>();
    }

    public async Task<ShipmentDto> CreateShipmentAsync(ShipmentDto shipment)
    {
        var response = await httpClient.PostAsJsonAsync("api/shipments", shipment);
        response.EnsureSuccessStatusCode();
        return (await response.Content.ReadFromJsonAsync<ShipmentDto>())!;
    }

    public async Task<ShipmentDto> UpdateShipmentStatusAsync(int id, ShipmentStatus status)
    {
        var response = await httpClient.PutAsJsonAsync($"api/shipments/{id}/status", new { Status = status });
        response.EnsureSuccessStatusCode();
        return (await response.Content.ReadFromJsonAsync<ShipmentDto>())!;
    }
}
```

### 4. Create EF Core entity and update DbContext on server

Create `ShipmentTracker/Data/Shipment.cs`:
```csharp
using System.ComponentModel.DataAnnotations;

namespace ShipmentTracker.Data;

public class Shipment
{
    public int Id { get; set; }

    [Required, MaxLength(20)]
    public string TrackingNumber { get; set; } = string.Empty;

    [Required, MaxLength(200)]
    public string Origin { get; set; } = string.Empty;

    [Required, MaxLength(200)]
    public string Destination { get; set; } = string.Empty;

    public int Status { get; set; }

    public DateTime ShippedDate { get; set; }
    public DateTime? EstimatedDelivery { get; set; }
    public DateTime? ActualDelivery { get; set; }

    [Required, MaxLength(200)]
    public string RecipientName { get; set; } = string.Empty;

    [MaxLength(500)]
    public string Description { get; set; } = string.Empty;
}
```

Edit `ShipmentTracker/Data/ApplicationDbContext.cs` to add `DbSet<Shipment>`:
```csharp
using Microsoft.AspNetCore.Identity.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore;

namespace ShipmentTracker.Data;

public class ApplicationDbContext(DbContextOptions<ApplicationDbContext> options) : IdentityDbContext<ApplicationUser>(options)
{
    public DbSet<Shipment> Shipments => Set<Shipment>();
}
```

### 5. Create server-side service implementation

Create `ShipmentTracker/Services/ShipmentServerService.cs`:
```csharp
using Microsoft.EntityFrameworkCore;
using ShipmentTracker.Client.Models;
using ShipmentTracker.Client.Services;
using ShipmentTracker.Data;

namespace ShipmentTracker.Services;

public class ShipmentServerService(IServiceProvider serviceProvider) : IShipmentService
{
    private ApplicationDbContext CreateDbContext()
    {
        return serviceProvider.CreateScope().ServiceProvider.GetRequiredService<ApplicationDbContext>();
    }

    public async Task<List<ShipmentDto>> GetAllShipmentsAsync()
    {
        using var db = CreateDbContext();
        var shipments = await db.Shipments.OrderByDescending(s => s.ShippedDate).ToListAsync();
        return shipments.Select(MapToDto).ToList();
    }

    public async Task<ShipmentDto?> GetShipmentByTrackingNumberAsync(string trackingNumber)
    {
        using var db = CreateDbContext();
        var shipment = await db.Shipments.FirstOrDefaultAsync(s => s.TrackingNumber == trackingNumber);
        return shipment is null ? null : MapToDto(shipment);
    }

    public async Task<ShipmentDto> CreateShipmentAsync(ShipmentDto dto)
    {
        using var db = CreateDbContext();
        var entity = new Shipment
        {
            TrackingNumber = dto.TrackingNumber,
            Origin = dto.Origin,
            Destination = dto.Destination,
            Status = (int)dto.Status,
            ShippedDate = dto.ShippedDate,
            EstimatedDelivery = dto.EstimatedDelivery,
            RecipientName = dto.RecipientName,
            Description = dto.Description
        };
        db.Shipments.Add(entity);
        await db.SaveChangesAsync();
        return MapToDto(entity);
    }

    public async Task<ShipmentDto> UpdateShipmentStatusAsync(int id, ShipmentStatus status)
    {
        using var db = CreateDbContext();
        var entity = await db.Shipments.FindAsync(id) ?? throw new KeyNotFoundException($"Shipment {id} not found");
        entity.Status = (int)status;
        if (status == ShipmentStatus.Delivered)
            entity.ActualDelivery = DateTime.UtcNow;
        await db.SaveChangesAsync();
        return MapToDto(entity);
    }

    private static ShipmentDto MapToDto(Shipment s) => new()
    {
        Id = s.Id,
        TrackingNumber = s.TrackingNumber,
        Origin = s.Origin,
        Destination = s.Destination,
        Status = (ShipmentStatus)s.Status,
        ShippedDate = s.ShippedDate,
        EstimatedDelivery = s.EstimatedDelivery,
        ActualDelivery = s.ActualDelivery,
        RecipientName = s.RecipientName,
        Description = s.Description
    };
}
