@code {
    [Inject] private IShipmentService ShipmentService { get; set; } = default!;

    private List<ShipmentDto> allShipments = [];
    private List<ShipmentDto> filteredShipments = [];
    private bool loading = true;
    private string? errorMessage;

    private string searchTerm = string.Empty;
    private string statusFilter = string.Empty;

    private bool showCreateForm;
    private bool creating;
    private ShipmentDto newShipment = new();

    protected override async Task OnInitializedAsync()
    {
        await LoadShipments();
    }

    private async Task LoadShipments()
    {
        loading = true;
        errorMessage = null;
        try
        {
            allShipments = await ShipmentService.GetAllShipmentsAsync();
            ApplyFilters();
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to load shipments: {ex.Message}";
        }
        finally
        {
            loading = false;
        }
    }

    private void ApplyFilters()
    {
        filteredShipments = allShipments.Where(s =>
        {
            if (!string.IsNullOrWhiteSpace(searchTerm))
            {
                var term = searchTerm.Trim();
                if (!s.TrackingNumber.Contains(term, StringComparison.OrdinalIgnoreCase) &&
                    !s.Destination.Contains(term, StringComparison.OrdinalIgnoreCase) &&
                    !s.RecipientName.Contains(term, StringComparison.OrdinalIgnoreCase))
                    return false;
            }
            if (!string.IsNullOrEmpty(statusFilter) && Enum.TryParse<ShipmentStatus>(statusFilter, out var fs))
            {
                if (s.Status != fs) return false;
            }
            return true;
        }).ToList();
    }

    private void ClearFilters()
    {
        searchTerm = string.Empty;
        statusFilter = string.Empty;
        ApplyFilters();
    }

    private async Task CreateShipment()
    {
        creating = true;
        try
        {
            await ShipmentService.CreateShipmentAsync(newShipment);
            newShipment = new();
            showCreateForm = false;
            await LoadShipments();
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to create shipment: {ex.Message}";
        }
        finally
        {
            creating = false;
        }
    }

    private async Task UpdateStatus(ShipmentDto shipment, ChangeEventArgs e)
    {
        if (e.Value is string val && int.TryParse(val, out var statusInt))
        {
            var newStatus = (ShipmentStatus)statusInt;
            try
            {
                var updated = await ShipmentService.UpdateShipmentStatusAsync(shipment.Id, newStatus);
                var index = allShipments.FindIndex(s => s.Id == shipment.Id);
                if (index >= 0)
                    allShipments[index] = updated;
                ApplyFilters();
            }
            catch (Exception ex)
            {
                errorMessage = $"Failed to update status: {ex.Message}";
            }
        }
    }

    private static List<ShipmentStatus> GetNextStatuses(ShipmentStatus current) => current switch
    {
        ShipmentStatus.Pending => [ShipmentStatus.PickedUp, ShipmentStatus.Cancelled],
        ShipmentStatus.PickedUp => [ShipmentStatus.InTransit, ShipmentStatus.Cancelled],
        ShipmentStatus.InTransit => [ShipmentStatus.OutForDelivery, ShipmentStatus.Cancelled],
        ShipmentStatus.OutForDelivery => [ShipmentStatus.Delivered, ShipmentStatus.Cancelled],
        _ => []
    };

    private static string GetStatusBadgeClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => "bg-secondary",
        ShipmentStatus.PickedUp => "bg-info",
        ShipmentStatus.InTransit => "bg-primary",
        ShipmentStatus.OutForDelivery => "bg-warning text-dark",
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.Cancelled => "bg-danger",
        _ => "bg-secondary"
    };
}
