### 5. Create server-side service implementation

Create `ShipmentTracker/Services/ShipmentServerService.cs`:
```csharp
using Microsoft.EntityFrameworkCore;
using ShipmentTracker.Client.Models;
using ShipmentTracker.Client.Services;
using ShipmentTracker.Data;

namespace ShipmentTracker.Services;

public class ShipmentServerService(IServiceProvider serviceProvider) : IShipmentService
{
    private ApplicationDbContext CreateDbContext()
    {
        return serviceProvider.CreateScope().ServiceProvider.GetRequiredService<ApplicationDbContext>();
    }

    public async Task<List<ShipmentDto>> GetAllShipmentsAsync()
    {
        using var db = CreateDbContext();
        var shipments = await db.Shipments.OrderByDescending(s => s.ShippedDate).ToListAsync();
        return shipments.Select(MapToDto).ToList();
    }

    public async Task<ShipmentDto?> GetShipmentByTrackingNumberAsync(string trackingNumber)
    {
        using var db = CreateDbContext();
        var shipment = await db.Shipments.FirstOrDefaultAsync(s => s.TrackingNumber == trackingNumber);
        return shipment is null ? null : MapToDto(shipment);
    }

    public async Task<ShipmentDto> CreateShipmentAsync(ShipmentDto dto)
    {
        using var db = CreateDbContext();
        var entity = new Shipment
        {
            TrackingNumber = dto.TrackingNumber,
            Origin = dto.Origin,
            Destination = dto.Destination,
            Status = (int)dto.Status,
            ShippedDate = dto.ShippedDate,
            EstimatedDelivery = dto.EstimatedDelivery,
            RecipientName = dto.RecipientName,
            Description = dto.Description
        };
        db.Shipments.Add(entity);
        await db.SaveChangesAsync();
        return MapToDto(entity);
    }

    public async Task<ShipmentDto> UpdateShipmentStatusAsync(int id, ShipmentStatus status)
    {
        using var db = CreateDbContext();
        var entity = await db.Shipments.FindAsync(id) ?? throw new KeyNotFoundException($"Shipment {id} not found");
        entity.Status = (int)status;
        if (status == ShipmentStatus.Delivered)
            entity.ActualDelivery = DateTime.UtcNow;
        await db.SaveChangesAsync();
        return MapToDto(entity);
    }

    private static ShipmentDto MapToDto(Shipment s) => new()
    {
        Id = s.Id,
        TrackingNumber = s.TrackingNumber,
        Origin = s.Origin,
        Destination = s.Destination,
        Status = (ShipmentStatus)s.Status,
        ShippedDate = s.ShippedDate,
        EstimatedDelivery = s.EstimatedDelivery,
        ActualDelivery = s.ActualDelivery,
        RecipientName = s.RecipientName,
        Description = s.Description
    };
}
