arguments.file_text:
@page "/track/{TrackingNumber}"
@attribute [Microsoft.AspNetCore.Authorization.Authorize]

@using ShipmentTracker.Client.Models
@using ShipmentTracker.Client.Services

<PageTitle>Track Shipment - @TrackingNumber</PageTitle>

<div class="container">
    <h2 class="mb-4">Shipment Tracking</h2>

    @if (loading)
    {
        <div class="d-flex justify-content-center my-5">
            <div class="spinner-border text-primary" role="status">
                <span class="visually-hidden">Loading...</span>
            </div>
        </div>
    }
    else if (shipment is null)
    {
        <div class="alert alert-warning">
            <h5>Shipment Not Found</h5>
            <p>No shipment found with tracking number <strong>@TrackingNumber</strong>.</p>
            <a href="/" class="btn btn-primary">Try Again</a>
        </div>
    }
    else
    {
        <div class="card shadow mb-4">
            <div class="card-header d-flex justify-content-between align-items-center">
                <h5 class="mb-0">Tracking: @shipment.TrackingNumber</h5>
                <span class="badge @GetStatusBadgeClass(shipment.Status) fs-6">@shipment.Status</span>
            </div>
            <div class="card-body">
                <div class="row">
                    <div class="col-md-6">
                        <dl>
                            <dt>Origin</dt>
                            <dd>@shipment.Origin</dd>
                            <dt>Destination</dt>
                            <dd>@shipment.Destination</dd>
                            <dt>Recipient</dt>
                            <dd>@shipment.RecipientName</dd>
                        </dl>
                    </div>
                    <div class="col-md-6">
                        <dl>
                            <dt>Shipped Date</dt>
                            <dd>@shipment.ShippedDate.ToString("MMMM dd, yyyy")</dd>
                            <dt>Estimated Delivery</dt>
                            <dd>
                                @if (shipment.EstimatedDelivery.HasValue)
                                {
                                    @shipment.EstimatedDelivery.Value.ToString("MMMM dd, yyyy")
                                }
                                else
                                {
                                    <span class="text-muted">Not available</span>
                                }
                            </dd>
                            <dt>Actual Delivery</dt>
                            <dd>
                                @if (shipment.ActualDelivery.HasValue)
                                {
                                    @shipment.ActualDelivery.Value.ToString("MMMM dd, yyyy 'at' h:mm tt")
                                }
                                else
                                {
                                    <span class="text-muted">Not yet delivered</span>
                                }
                            </dd>
                        </dl>
                    </div>
                </div>
                @if (!string.IsNullOrWhiteSpace(shipment.Description))
                {
                    <div class="mt-3">
                        <dt>Description</dt>
                        <dd>@shipment.Description</dd>
                    </div>
                }
            </div>
        </div>

        <!-- Status Progress -->
        <div class="card shadow">
            <div class="card-body">
                <h5 class="card-title">Shipment Progress</h5>
                <div class="progress mt-3" style="height: 30px;">
                    <div class="progress-bar @GetProgressBarClass(shipment.Status)" 
                         role="progressbar" 
                         style="width: @GetProgressPercentage(shipment.Status)%"
                         aria-valuenow="@GetProgressPercentage(shipment.Status)" 
                         aria-valuemin="0" aria-valuemax="100">
                        @shipment.Status
                    </div>
                </div>
                <div class="d-flex justify-content-between mt-2 small text-muted">
                    <span>Pending</span>
                    <span>Picked Up</span>
                    <span>In Transit</span>
                    <span>Out for Delivery</span>
                    <span>Delivered</span>
                </div>
            </div>
        </div>

        <div class="mt-3">
            <a href="/" class="btn btn-outline-secondary">Track Another Shipment</a>
        </div>
    }
</div>

@code {
    [Parameter] public string TrackingNumber { get; set; } = string.Empty;
    [Inject] private IShipmentService ShipmentService { get; set; } = default!;

    private ShipmentDto? shipment;
    private bool loading = true;

