                            <th>Actions</th>
                        </tr>
                    </thead>
                    <tbody>
                        @if (!filteredShipments.Any())
                        {
                            <tr><td colspan="7" class="text-center text-muted py-4">No shipments found.</td></tr>
                        }
                        @foreach (var s in filteredShipments)
                        {
                            <tr>
