                            <InputText class="form-control" @bind-Value="newShipment.RecipientName" />
                        </div>
                        <div class="col-md-6">
                            <label class="form-label">Estimated Delivery</label>
                            <InputDate class="form-control" @bind-Value="newShipment.EstimatedDelivery" />
                        </div>
                        <div class="col-12">
                            <label class="form-label">Description</label>
                            <InputText class="form-control" @bind-Value="newShipment.Description" />
                        </div>
                        <div class="col-12">
                            <button type="submit" class="btn btn-success" disabled="@creating">
                                @(creating ? "Creating..." : "Create Shipment")
                            </button>
                        </div>
                    </div>
                </EditForm>
            </div>
        </div>
    }

    <!-- Filters -->
    <div class="card shadow mb-3">
        <div class="card-body">
            <div class="row g-3 align-items-end">
                <div class="col-md-4">
                    <label class="form-label">Search</label>
                    <input type="text" class="form-control" placeholder="Tracking number, destination, or recipient"
                           @bind="searchTerm" @bind:event="oninput" @bind:after="ApplyFilters" />
                </div>
                <div class="col-md-3">
                    <label class="form-label">Status Filter</label>
                    <select class="form-select" @bind="statusFilter" @bind:after="ApplyFilters">
                        <option value="">All Statuses</option>
                        @foreach (var status in Enum.GetValues<ShipmentStatus>())
                        {
                            <option value="@status">@status</option>
                        }
                    </select>
                </div>
                <div class="col-md-2">
                    <button class="btn btn-outline-secondary" @onclick="ClearFilters">Clear</button>
                </div>
            </div>
        </div>
    </div>

    @if (loading)
    {
        <div class="d-flex justify-content-center my-5">
            <div class="spinner-border text-primary" role="status">
                <span class="visually-hidden">Loading...</span>
            </div>
        </div>
    }
    else if (errorMessage is not null)
    {
        <div class="alert alert-danger">@errorMessage</div>
    }
    else
    {
        <div class="card shadow">
            <div class="table-responsive">
                <table class="table table-hover mb-0">
                    <thead class="table-light">
                        <tr>
                            <th>Tracking #</th>
                            <th>Destination</th>
                            <th>Recipient</th>
                            <th>Shipped</th>
                            <th>Est. Delivery</th>
                            <th>Status</th>
                            <th>Actions</th>
                        </tr>
                    </thead>
                    <tbody>
                        @if (!filteredShipments.Any())
                        {
                            <tr><td colspan="7" class="text-center text-muted py-4">No shipments found.</td></tr>
                        }
                        @foreach (var s in filteredShipments)
                        {
                            <tr>
                                <td>
                                    <a href="track/@Uri.EscapeDataString(s.TrackingNumber)">@s.TrackingNumber</a>
                                </td>
                                <td>@s.Destination</td>
                                <td>@s.RecipientName</td>
                                <td>@s.ShippedDate.ToString("MMM dd, yyyy")</td>
                                <td>@(s.EstimatedDelivery?.ToString("MMM dd, yyyy") ?? "—")</td>
                                <td><span class="badge @GetStatusBadgeClass(s.Status)">@s.Status</span></td>
                                <td>
                                    @if (s.Status != ShipmentStatus.Delivered && s.Status != ShipmentStatus.Cancelled)
                                    {
                                        <div class="btn-group btn-group-sm">
                                            <select class="form-select form-select-sm" style="width: auto;"
                                                    @onchange="(e) => UpdateStatus(s, e)">
                                                <option value="" selected disabled>Update…</option>
                                                @foreach (var status in GetNextStatuses(s.Status))
                                                {
                                                    <option value="@((int)status)">@status</option>
                                                }
                                            </select>
                                        </div>
                                    }
                                </td>
                            </tr>
                        }
                    </tbody>
                </table>
            </div>
        </div>
        <p class="text-muted mt-2">Showing @filteredShipments.Count of @allShipments.Count shipments</p>
    }
</div>

@code {
    [Inject] private IShipmentService ShipmentService { get; set; } = default!;

    private List<ShipmentDto> allShipments = [];
    private List<ShipmentDto> filteredShipments = [];
    private bool loading = true;
    private string? errorMessage;

    private string searchTerm = string.Empty;
    private string statusFilter = string.Empty;

    private bool showCreateForm;
    private bool creating;
    private ShipmentDto newShipment = new();

    protected override async Task OnInitializedAsync()
    {
        await LoadShipments();
    }

    private async Task LoadShipments()
    {
        loading = true;
        errorMessage = null;
        try
        {
            allShipments = await ShipmentService.GetAllShipmentsAsync();
            ApplyFilters();
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to load shipments: {ex.Message}";
        }
        finally
        {
            loading = false;
        }
    }

    private void ApplyFilters()
    {
        filteredShipments = allShipments.Where(s =>
        {
            if (!string.IsNullOrWhiteSpace(searchTerm))
            {
                var term = searchTerm.Trim();
                if (!s.TrackingNumber.Contains(term, StringComparison.OrdinalIgnoreCase) &&
                    !s.Destination.Contains(term, StringComparison.OrdinalIgnoreCase) &&
                    !s.RecipientName.Contains(term, StringComparison.OrdinalIgnoreCase))
                    return false;
            }
            if (!string.IsNullOrEmpty(statusFilter) && Enum.TryParse<ShipmentStatus>(statusFilter, out var fs))
            {
                if (s.Status != fs) return false;
            }
            return true;
        }).ToList();
    }

    private void ClearFilters()
    {
        searchTerm = string.Empty;
        statusFilter = string.Empty;
        ApplyFilters();
    }

    private async Task CreateShipment()
    {
        creating = true;
        try
        {
            await ShipmentService.CreateShipmentAsync(newShipment);
            newShipment = new();
            showCreateForm = false;
            await LoadShipments();
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to create shipment: {ex.Message}";
        }
        finally
        {
            creating = false;
        }
    }

    private async Task UpdateStatus(ShipmentDto shipment, ChangeEventArgs e)
    {
        if (e.Value is string val && int.TryParse(val, out var statusInt))
        {
            var newStatus = (ShipmentStatus)statusInt;
            try
            {
                var updated = await ShipmentService.UpdateShipmentStatusAsync(shipment.Id, newStatus);
                var index = allShipments.FindIndex(s => s.Id == shipment.Id);
                if (index >= 0)
                    allShipments[index] = updated;
                ApplyFilters();
            }
            catch (Exception ex)
            {
                errorMessage = $"Failed to update status: {ex.Message}";
            }
        }
    }

    private static List<ShipmentStatus> GetNextStatuses(ShipmentStatus current) => current switch
    {
        ShipmentStatus.Pending => [ShipmentStatus.PickedUp, ShipmentStatus.Cancelled],
        ShipmentStatus.PickedUp => [ShipmentStatus.InTransit, ShipmentStatus.Cancelled],
        ShipmentStatus.InTransit => [ShipmentStatus.OutForDelivery, ShipmentStatus.Cancelled],
        ShipmentStatus.OutForDelivery => [ShipmentStatus.Delivered, ShipmentStatus.Cancelled],
        _ => []
    };

    private static string GetStatusBadgeClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => "bg-secondary",
        ShipmentStatus.PickedUp => "bg-info",
        ShipmentStatus.InTransit => "bg-primary",
        ShipmentStatus.OutForDelivery => "bg-warning text-dark",
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.Cancelled => "bg-danger",
        _ => "bg-secondary"
    };
}
